// main/almanac_content.h — on-screen content of the almanac ([PURE], host-testable).
//
// main/almanac_content.c is generated by tools/almanac/gen_assets.mjs from tools/almanac/content.txt,
// the reviewed copy deck. Index conventions match almanac_cal.h: stems 甲..癸, branches 子..亥 and
// zodiac animals 鼠..猪, compass clockwise from 正北, gods 青龙..勾陈, 建除 gods 建..闭,
// double-hours 子时..亥时.
#pragma once

#include <stdbool.h>
#include <stdint.h>

#define ALMANAC_FACE_COUNT 6
#define ALMANAC_ITEMS_PER_FACE 20
#define ALMANAC_ITEM_COUNT (ALMANAC_FACE_COUNT * ALMANAC_ITEMS_PER_FACE)

// Faces, in copy-deck order.
enum { ALMANAC_FACE_ROOM = 0, ALMANAC_FACE_SERVER, ALMANAC_FACE_NETWORK, ALMANAC_FACE_SECURITY, ALMANAC_FACE_PEOPLE, ALMANAC_FACE_CLOUD };

typedef enum { ALMANAC_YI = 0, ALMANAC_JI = 1 } almanac_side_t;

// An item is addressed by face * ALMANAC_ITEMS_PER_FACE + index.
const char *almanac_item_text(almanac_side_t side, int item);

// 彭祖百忌 lines: 0..9 by day stem, 10..21 by day branch.
#define ALMANAC_BAIJI_COUNT 22
const char *almanac_baiji_line(int line);

const char *almanac_zhixing_name(int god);
const char *almanac_zhixing_gloss(int god);
const char *almanac_chong_object(int clashed_zodiac);
const char *almanac_chong_note(int clashed_zodiac);
// Where 煞方 points inside the server room, for one of the four cardinal compass directions.
const char *almanac_sha_place(int compass);
const char *almanac_tianshen_name(int god);

#define ALMANAC_LUCKY_GOD_COUNT 20
#define ALMANAC_UNLUCKY_GOD_COUNT 22
const char *almanac_god_lucky(int n);
const char *almanac_god_unlucky(int n);

const char *almanac_hour_note(int hour);
const char *almanac_hour_god_gloss(int god);
const char *almanac_day_type_line(int huangdao); // 1 = 黄道日, 0 = 黑道日

#define ALMANAC_DIR_KIND_COUNT 4
enum { ALMANAC_DIR_LABEL_CAI = 0, ALMANAC_DIR_LABEL_XI, ALMANAC_DIR_LABEL_FU, ALMANAC_DIR_LABEL_YANG_GUI };
const char *almanac_dir_label(int kind);
const char *almanac_dir_say(int kind);

#define ALMANAC_PROTOCOL_COUNT 16
#define ALMANAC_PORT_COUNT 16
#define ALMANAC_TOOL_COUNT 16
#define ALMANAC_COLOR_COUNT 8
#define ALMANAC_NUMBER_COUNT 12
const char *almanac_protocol_name(int n);
const char *almanac_protocol_note(int n);
const char *almanac_port_number(int n);
const char *almanac_port_note(int n);
const char *almanac_tool(int n);
const char *almanac_color(int n);
const char *almanac_number(int n);

#define ALMANAC_LUCK_CATEGORY_COUNT 5
const char *almanac_luck_name(int category);
// stars is 1..5.
const char *almanac_luck_line(int category, int stars);

#define ALMANAC_MATTER_COUNT 12
const char *almanac_matter(int matter);

// 择吉日 rules: 建除 gods that make a day lucky and avoided (12 bits each), and the 彭祖百忌 lines
// that suppress the matter on their days (22 bits, see almanac_baiji_line).
typedef struct {
    uint32_t lucky;
    uint32_t avoid;
    uint32_t skip_lines;
} almanac_matter_rule_t;
void almanac_matter_rule(int matter, uint32_t *lucky, uint32_t *avoid, uint32_t *skip_lines);

// 120-bit mask over 宜 items.
typedef struct {
    uint64_t lo;
    uint64_t hi;
} almanac_item_mask_t;

// True when the 彭祖百忌 line keeps the 宜 item off the same card.
bool almanac_line_skips_item(int line, int item);
// 吉神 the line keeps off the same card, as a mask over almanac_god_lucky().
uint32_t almanac_hidden_lucky_gods(int line);

const char *almanac_stem(int stem);
const char *almanac_branch(int branch);
const char *almanac_zodiac(int zodiac);
const char *almanac_compass(int compass);
const char *almanac_weekday_name(int weekday); // 0 = Monday
const char *almanac_lunar_month(int month); // 1..12
const char *almanac_lunar_day(int day); // 1..30
